def find_files(d, pattern, max_depth=5):
    results = []
    if not os.path.exists(d):
        return results
    depth = d.replace(workspace, '').count(os.sep) + 1
    if depth > max_depth:
        return results

    for f in sorted(os.listdir(d)):
        path = os.path.join(d, f)
        if os.path.isdir(path):
            if depth < max_depth:
                results.extend(find_files(path, pattern, max_depth))
        elif pattern in f.lower():
            results.append(path)
    return results

