test_in = G.get('Test input', [])

print("Finding leftmost cell for each color:")
color_min_x = {}
for row_idx, row in enumerate(test_in):
    for col_idx, val in enumerate(row):
        if val > 0:
            if val not in color_min_x:
                color_min_x[val] = col_idx
            else:
                color_min_x[val] = min(color_min_x[val], col_idx)

print(f"Colors and their leftmost column: {color_min_x}")

