# Build output with correct order
def find_all_shapes(grid):
    shapes = {}
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] > 0 and (r,c) not in visited:
                color = grid[r][c]
                cells = []
                to_visit = [(r, c)]
                while to_visit:
                    cr, cc = to_visit.pop(0)
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                to_visit.append((nr, nc))

                min_r = min(c[0] for c in cells)
                min_c = min(c[1] for c in cells)
                normalized = [(c[0]-min_r, c[1]-min_c) for c in cells]

                if color not in shapes:
                    shapes[color] = []
                shapes[color].append(normalized)

    return shapes

